/**
 * Meetrix - Shared Branding Configuration
 * Centralized branding definitions, asset paths, and offline base64 data URIs.
 */
(function (root) {
  'use strict';

  // Self-contained base64 PNG data URI for offline reports and standalone rendering
  const LOGO_BASE64 = "";

  const MeetrixBranding = {
    brandName: 'MEETRIX AI',
    wordmark: 'MEETRIX',
    badge: 'AI',
    tagline: 'Capture • Track • Transcribe • Summarize',
    logoDataUri: 'data:image/png;base64,' + LOGO_BASE64,

    /**
     * Resolves extension-relative assets safely across content scripts, popups, and Node.js.
     * @param {string} relativePath e.g. 'icons/icon48.png'
     * @returns {string}
     */
    getAssetUrl(relativePath) {
      if (typeof chrome !== 'undefined' && chrome.runtime && typeof chrome.runtime.getURL === 'function') {
        try {
          return chrome.runtime.getURL(relativePath);
        } catch (_) {}
      }
      return relativePath;
    },

    getEmblemUrl() {
      return this.getAssetUrl('icons/icon48.png');
    },

    getLargeEmblemUrl() {
      return this.getAssetUrl('icons/meetrix-emblem.png');
    },

    getFullLogoUrl() {
      return this.getAssetUrl('icons/meetrix-logo.png');
    }
  };

  root.MeetrixBranding = MeetrixBranding;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = MeetrixBranding;
  }
})(typeof window !== 'undefined' ? window : (typeof self !== 'undefined' ? self : globalThis));
